  for(i = 0; i < 32; i++) patofs[i] = f->readInt(2);	// pattern offset table
  if (f->error()) {
    fp.close(f); return false;
  }

  init_trackord();		// patterns
  for(i=0;i<32;i++)
    if(patofs[i]) {
