      }
    } else
      memset(trackord[i],0,9*2);
  fp.close(f);

  // convert replay data
  for(i=0;i<32*9;i++)	// convert patterns
    for(j=0;j<64;j++) {
      if(tracks[i][j].note == 15)
	tracks[i][j].note = 127;
