    delete [] org;
    fp.close(f);
    return false;
  }

  if(version < 5) {
    for(i=0;i<numpats;i++)
      for(j=0;j<64;j++)
	for(k=0;k<9;k++) {
	  struct Tracks	*track = &tracks[i * 9 + k][j];
	  unsigned char	*o = &org[i*64*t*4+j*t*4+k*4];

	  track->note = o[0] == 255 ? 127 : o[0];
	  track->inst = o[1];
	  track->command = o[2] < sizeof(convfx) ? convfx[o[2]] : 255;
	  track->param2 = o[3] & 0x0f;
