		char buffer[512];
		#if GRAVITY_ENABLE_INT64
		snprintf(buffer, sizeof(buffer), "%" PRId64, v.n);
		#else
		snprintf(buffer, sizeof(buffer), "%d", v.n);
		#endif
		return VALUE_FROM_CSTRING(vm, buffer);

	}
