            p_buf->offset);

  for (uint32_t frame = 0; frame < numFrames; ++frame) {
    {
      numChannels = opus_packet_get_nb_channels(pBuffer);

      ret_val = opus_decode(a2dp_opus_decoder_cb.opus_handle,
                            reinterpret_cast<unsigned char*>(pBuffer),
