    /*
     *	spot our marker in the URL.  It'll look like "/WebObjects-n.ext/"
     */
    s = (url != NULL) ? url : "";
    while ( (s <= url + (len - WebObjects_LEN)) && (webobjects == NULL) && (*s != '?') ) {
