    }
    if (webobjects == NULL)
        return WOURLInvalidPrefix;	/* bail if "WebObjects" not in URL */

    s = webobjects + WebObjects_LEN;	/* just beyond "WebObjects" */
    for (end = s; (end < url + len) && (*end != '?') && (*end != '/'); end++)
        /* find end of CGI moniker */;

