			if (result != MP_OK)
			{
				delete[] samplePtrs;
				return result;
			}

			if (adpcm)
				// no longer needed
				smp[s].res = 0;			

			s++;

		}

	}

	delete[] samplePtrs;

	header->smpnum = s;

	strcpy(header->tracker,"Screamtracker 3");

	module->setDefaultPanning();

	module->postProcessSamples();

	return MP_OK;	
}

